and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from dual
union all
select '1' as test_id, 14 as line_num, '资金流出-资产端' as col_value1, '资产到期' as col_value2, '拆入到期' as col_value3, (select DATE_FORMAT(round(IFNULL(t.value, 0),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '10012'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from dual
union all
select '1' as test_id, 15 as line_num, '' as col_value1, '' as col_value2, '债券借贷到期' as col_value3, (select DATE_FORMAT(round(IFNULL(t.value, 0),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '10013'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from dual
