select '1' as test_id, 16 as line_num, '' as col_value1, '融入资产到期' as col_value2, '质押式正回购到期' as col_value3, (select DATE_FORMAT(round(IFNULL(t.value, 0),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '10014'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from dual
union all
select '1' as test_id, 17 as line_num, '' as col_value1, '' as col_value2, '买断式正回购到期' as col_value3, (select DATE_FORMAT(round(IFNULL(t.value, 0),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '10014001'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from dual
union all
select '1' as test_id, 18 as line_num, '资金流出-资产端合计' as col_value1, '' as col_value2, '' as col_value3, (select DATE_FORMAT(round(sum(IFNULL(t.value, 0)),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '1001004'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from dual
union all
select '1' as test_id, 19 as line_num, '资金流出-产品赎回' as col_value1, '轻度' as col_value2, '' as col_value3, (select DATE_FORMAT(round(IFNULL(ts.light_value, 0),2)) as amount from STT_STRESS_INDDATA t left join STT_INDDATA_LMH ts on t.seq_no=ts.seq_no where t.ind_id = '10011'
and t.test_id=#{flowTestId} and ts.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from dual
union all
select '1' as test_id, 20 as line_num, '' as col_value1, '中度' as col_value2, '' as col_value3, (select DATE_FORMAT(round(IFNULL(ts.medium_value, 0),2)) as amount from STT_STRESS_INDDATA t left join STT_INDDATA_LMH ts on t.seq_no=ts.seq_no where t.ind_id = '10011'
and t.test_id=#{flowTestId} and ts.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from dual
union all
select '1' as test_id, 21 as line_num, '' as col_value1, '重度' as col_value2, '' as col_value3, (select DATE_FORMAT(round(IFNULL(ts.heavy_value, 0),2)) as amount from STT_STRESS_INDDATA t left join STT_INDDATA_LMH ts on t.seq_no=ts.seq_no where t.ind_id = '10011'
and t.test_id=#{flowTestId} and ts.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from dual
union all
select '1' as test_id, 22+t1.numid as line_num, t1.col_value1 as col_value1, t1.item_value as col_value2, '' as col_value3, DATE_FORMAT(round(IFNULL(t.value, 0),2)) as amount, '' as remarks from (select case when numid=1 then '一级流动性资产储备明细' else '' end as col_value1, sdl.item_value, smd.dict_code, smd.souce_value, @rownum:=@rownum+1 as numid from (SELECT @rownum:=0) r,STT_MAPPING_DET smd left join sys_datadict_list sdl on smd.dict_code=sdl.dict_code and smd.souce_value=sdl.item_code where smd.mapping_id='1001') t1 left join (select * from STT_STRESS_INDDATA t where t.ind_id = '20001'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
)t on t1.dict_code=SUBSTRING(t.flowasset_type,0,instr(t.flowasset_type,':')-1) and t1.souce_value=SUBSTRING(t.flowasset_type,instr(t.flowasset_type,':')+1,length(t.flowasset_type)) order by smd.dict_code desc,smd.souce_value asc union all
select '1' as test_id, 222+t1.numid as line_num, t1.col_value1 as col_value1, t1.item_value as col_value2, '' as col_value3, DATE_FORMAT(round(IFNULL(t.value, 0),2)) as amount, '' as remarks from (select case when (numid)=1 then '二级流动性资产储备明细' else '' end as col_value1, sdl.item_value, smd.dict_code, smd.souce_value, @rownum:=@rownum+1 as numid from (SELECT @rownum:=0) r,STT_MAPPING_DET smd left join sys_datadict_list sdl on smd.dict_code=sdl.dict_code and smd.souce_value=sdl.item_code where smd.mapping_id='1002') t1 left join (select * from STT_STRESS_INDDATA t where t.ind_id = '20002'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
)t on t1.dict_code=SUBSTRING(t.flowasset_type,0,instr(t.flowasset_type,':')-1) and t1.souce_value=SUBSTRING(t.flowasset_type,instr(t.flowasset_type,':')+1,length(t.flowasset_type))
order by smd.dict_code desc,smd.souce_value asc, TEST_ID,LINE_NUM
